import numpy as np
NAME = '과매도인데 1년 오름세(RSI14 낮은 순)'
def rsi(F, n=14):
    lr = np.nan_to_num(F.lr)
    up = F.roll(np.where(lr > 0, lr, 0.0), n, 'mean'); dn = F.roll(np.where(lr < 0, -lr, 0.0), n, 'mean')
    return 100 * up / (up + dn + 1e-12)
def score(F):
    r = rsi(F); yr = F.ret(240)
    s = -r
    return np.where(yr > 0, s, np.nan)

