import numpy as np
NAME='연속으로 내린 날이 많은 곳'
def streak(x):
    s=np.zeros(x.shape); 
    for t in range(1,x.shape[0]):
        s[t]=np.where(x[t]<0, s[t-1]+1, 0)
    return s
def score(F):
    lr=F.lr
    s=streak(np.nan_to_num(lr,nan=0.0))
    s=s+0.001*(-F.ret(5))  # tie-break
    s[np.isnan(F.C)]=np.nan
    return s

