import numpy as np
NAME = '업종 1등만 남겨 고름(오래 오른 힘)'
def only_leader(F, base):
    out = np.full(base.shape, np.nan)
    inds = np.asarray(F.ind)
    for g in set(inds):
        idx = np.where(inds == g)[0]
        sub = base[:, idx]
        filled = np.where(np.isnan(sub), -np.inf, sub)
        am = filled.argmax(axis=1)
        ok = np.isfinite(filled.max(axis=1))
        for t in np.where(ok)[0]:
            out[t, idx[am[t]]] = sub[t, am[t]]
    return out
def score(F):
    return only_leader(F, F.rel(60))

