import numpy as np
NAME = '눈길 몰렸다 식은 곳(종가만 · 큰 움직임)'
def sh(X, k):
    Y = np.full(X.shape, np.nan); Y[k:] = X[:-k]; return Y
def score(F):
    a = np.abs(F.lr - F.mkt[:, None])
    past = sh(F.roll(a, 10, 'mean'), 20)
    base = F.roll(a, 120, 'mean')
    recent = F.roll(a, 5, 'mean')
    return F.zcs(past - base) + F.zcs(past - recent)

